'use client';
import { useEffect, useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import api from '@/lib/api';
import { DollarSign, ShoppingBag, Users, Store } from 'lucide-react';
import { Bar, Doughnut } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    ArcElement,
} from 'chart.js';

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    ArcElement
);

const StatCard = ({ title, value, icon: Icon, color, trend }) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <div className="flex items-center justify-between mb-4">
            <div className={`p-3 rounded-full ${color} bg-opacity-10`}>
                <Icon className={color.replace('bg-', 'text-')} size={24} />
            </div>
            {trend && (
                <span className={`text-xs font-semibold px-2 py-1 rounded-full ${trend > 0 ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                    {trend > 0 ? '+' : ''}{trend}%
                </span>
            )}
        </div>
        <h3 className="text-gray-500 text-sm font-medium">{title}</h3>
        <p className="text-2xl font-bold text-gray-800 mt-1">{value}</p>
    </div>
);

export default function Dashboard() {
    const { user } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                // Fallback demo data if API fails or is not ready
                const demoData = {
                    totalRevenue: 125000,
                    activeOrders: 42,
                    totalUsers: 156,
                    totalRestaurants: 12,
                    revenueChart: {
                        labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
                        data: [12000, 19000, 15000, 22000, 28000, 35000, 42000],
                    },
                    orderStatus: {
                        labels: ['Preparing', 'Ready', 'Delivered', 'Cancelled'],
                        data: [12, 8, 45, 3],
                    }
                };

                // Try fetching real data
                try {
                    // Uncomment when backend is ready to serve this
                    // const res = await api.get('/admin/dashboard');
                    // setStats(res.data);
                    setStats(demoData);
                } catch (e) {
                    setStats(demoData);
                }
            } catch (error) {
                console.error('Error fetching stats:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchStats();
    }, [user]);

    if (loading) return <div className="p-10 text-center">Loading stats...</div>;

    const barData = {
        labels: stats.revenueChart.labels,
        datasets: [
            {
                label: 'Revenue (₹)',
                data: stats.revenueChart.data,
                backgroundColor: '#FF6B35',
                borderRadius: 4,
            },
        ],
    };

    const doughnutData = {
        labels: stats.orderStatus.labels,
        datasets: [
            {
                data: stats.orderStatus.data,
                backgroundColor: ['#f59e0b', '#3b82f6', '#10b981', '#ef4444'],
                borderWidth: 0,
            },
        ],
    };

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-gray-800">Overview</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard title="Total Revenue" value={`₹${stats.totalRevenue.toLocaleString()}`} icon={DollarSign} color="bg-green-500" trend={12} />
                <StatCard title="Active Orders" value={stats.activeOrders} icon={ShoppingBag} color="bg-blue-500" trend={5} />
                <StatCard title="Total Users" value={stats.totalUsers} icon={Users} color="bg-purple-500" trend={8} />
                <StatCard title="Restaurants" value={stats.totalRestaurants} icon={Store} color="bg-orange-500" trend={0} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <h2 className="text-lg font-bold text-gray-800 mb-4">Weekly Revenue</h2>
                    <div className="h-64">
                        <Bar data={barData} options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } } }} />
                    </div>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <h2 className="text-lg font-bold text-gray-800 mb-4">Order Status</h2>
                    <div className="h-64 flex justify-center">
                        <Doughnut data={doughnutData} options={{ responsive: true, maintainAspectRatio: false, cutout: '70%', plugins: { legend: { position: 'bottom' } } }} />
                    </div>
                </div>
            </div>
        </div>
    );
}
